        <div class="lg:flex"> 
            <?php 
            // 1. Configurar os argumentos da Query
            $args_equipe = array(
                'post_type'      => 'equipe',          // Nosso CPT
                'posts_per_page' => -1,                // Mostrar todos
                'orderby'        => 'date',            // Ordenar por data
                'order'          => 'ASC',             // Mais antigos primeiro
            );
            
            // 2. Criar a nova WP_Query
            $query_equipe = new WP_Query( $args_equipe );
            
            // 3. O Loop
            if ( $query_equipe->have_posts() ) :
                while( $query_equipe->have_posts() ) : $query_equipe->the_post();
                    
                    // Coletar links sociais
                    $link_facebook = get_field('link_facebook_equipe');
                    $link_instagram = get_field('link_instagram_equipe');
            ?>
            
            <a href="<?php the_permalink(); ?>" class="group flex flex-col items-center lg:mb-0 mb-4 lg:w-1/2 px-4">
                
                <?php if ( has_post_thumbnail() ) : ?>
                    <?php the_post_thumbnail( 'thumbnail', array(
                        'class' => 'rounded-full mb-8 w-40 h-40 object-cover object-center'
                    )); ?>
                <?php else: ?>
                    <div class="rounded-full mb-8 w-40 h-40 bg-gray-300"></div>
                <?php endif; ?>
                
                <h3 class="text-2xl text-brand-azul-escuro group-hover:text-brand-marrom transition-colors"><?php the_title(); ?></h3>
                
                <small class="uppercase font-sans text-brand-azul-escuro/50 mb-6"><?php the_field('profissao_equipe'); ?></small>
                
                <div class="font-sans text-brand-azul-escuro text-center mb-4">
                    <?php the_excerpt(); ?>
                </div>
            </a>
            <?php 
                endwhile; 
                wp_reset_postdata(); // Importante: restaura o post global
            endif; 
            ?>
